        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter,deque
    cnt=Counter(c for r in g for c in r)
    bg=cnt.most_common(1)[0][0]
    oc=[c for c,v in cnt.items() if v<cnt[bg]][0]
    ext=[[False]*w for _ in range(h)]
    q=deque()
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg: ext[i][j]=True; q.append((i,j))
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not ext[i][j]: ext[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not ext[a][b]:
                ext[a][b]=True; q.append((a,b))
    holes={(i,j) for i in range(h) for j in range(w) if g[i][j]==bg and not ext[i][j]}
    out=[r[:] for r in g]
    for i,j in holes:
        # fill the full row band between topmost hole row and bottom hole row? just fill contiguous run
        rows=sorted({i for i,j in holes})
        cols=sorted({j for i,j in holes})
        top=rows[0]; bot=max(rows)
        left=cols[0]; right=max(cols)
        for a in range(top,bot+1):
            for b in range(left,right+1):
                if g[a][b]==oc: out[a][b]=bg
    return out
